// The regular expression grammar: one line per family of report, so that a
// wrong SPAN shows as a wrong line and not only as a wrong count.
const unknownFlag = /a/q;
const duplicateFlag = /a/gg;
const uvTogether = /a/uv;
const nothingToRepeat = /(?:)*+/u;
const outOfOrderQuantifier = /a{3,2}/u;
const incompleteQuantifier = /a{,2}/u;
const missingBrace = /a{2/u;
const unbalancedParen = /a)/;
const unbalancedBracketU = /a]/u;
const groupNotFound = /\k<name>/;
const duplicateGroupName = /(?<a>x)(?<a>y)/;
const backreferenceTooBig = /(a)\3/;
const backreferenceNoGroups = /\1/u;
const emptyGroupName = /(?<>x)/;
const badPropertyName = /\p{Scrpt=Greek}/u;
const badPropertyValue = /\p{Script=Nosuch}/u;
const badLoneProperty = /\p{Nosuch}/u;
const propertyWithoutU = /\p{Letter}/;
const stringsPropertyWithoutV = /\p{RGI_Emoji}/u;
const classRangeOutOfOrder = /[b-a]/;
const classRangeBounded = /[\d-a]/u;
const controlEscape = /\c1/u;
const characterNotEscapable = /\q/u;
const octalInClass = /[\1]/;
const decimalInClass = /[\8]/;
const bracedEscapeWithoutU = /\u{41}/;
const reservedDoublePunctuator = /[a&&&b]/v;
const mixedOperators = /[\q{ab}--c&&d]/v;
const negatedStrings = /[^\q{ab}]/v;
const qOutsideClass = /\q{ab}/v;
const subpatternMinusNoFlags = /(?-:a)/;
const subpatternBadFlag = /(?g:a)/;
const kWithoutName = /\k(?<a>x)/;
const expectedClassSetOperand = /[--a]/v;
const qWithoutBraces = /[\qab]/v;
const reservedDoublePunctuator2 = /[a##b]/v;
const expectedPropertyName = /\p{=Greek}/u;
const expectedPropertyValue = /\p{Script=}/u;
const expectedNameOrValue = /\p{}/u;
const pWithoutBraces = /\pL/u;
